from PIL import Image, ImageDraw, ImageOps
import os

def crop_circular(image_path, output_path):
    img = Image.open(image_path).convert("RGBA")
    
    # Dimensions of standard sketch generated by the user are 1024x1024.
    # In the drawing, the smartphone is on the right.
    # The logo circle is centered at approximately X=775, Y=528 with a radius of 85.
    width, height = img.size
    
    scale_x = width / 1024.0
    scale_y = height / 1024.0
    
    # Calculate bounding box of the logo circle
    left = int((775 - 85) * scale_x)
    top = int((528 - 85) * scale_y)
    right = int((775 + 85) * scale_x)
    bottom = int((528 + 85) * scale_y)
    
    box = (left, top, right, bottom)
    cropped = img.crop(box)
    
    # Cut borders into a circular shape using a transparency mask
    size = cropped.size
    mask = Image.new('L', size, 0)
    draw = ImageDraw.Draw(mask)
    draw.ellipse((0, 0) + size, fill=255)
    
    output = ImageOps.fit(cropped, size, centering=(0.5, 0.5))
    output.putalpha(mask)
    
    # Save the output image
    output.save(output_path, "PNG")
    print(f"Successfully cropped circular logo and saved to {output_path}")

